import sqlite3
import base64
import re

conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

def decode_b64(text):
    m = re.search(r'-enc\s+([A-Za-z0-9+/=]+)', text, re.I)
    if m:
        encoded = m.group(1)
        # Pad base64
        encoded += "=" * ((4 - len(encoded) % 4) % 4)
        try:
            return base64.b64decode(encoded).decode('utf-16le', errors='ignore')
        except:
            try:
                return base64.b64decode(encoded).decode('utf-8', errors='ignore')
            except:
                pass
    return None

cur.execute("SELECT event_id, event_code, host, user, message FROM events WHERE event_code IN (800, 4103) ORDER BY timestamp")
for r in cur.fetchall():
    msg = r['message']
    ha_match = re.search(r'HostApplication=([^\r\n]+)', msg)
    if ha_match:
        ha = ha_match.group(1)
        decoded = decode_b64(ha)
        if decoded:
            print(f"{r['event_id']} | {r['host']} | Decoded: {decoded[:200]}")
            break # Just need to see one
EOF
